def scored_rect_transform(grid, min_density=.75, bg_penalty=5.0, noise_penalty=1.0):
 H,W=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 out=[[bg]*W for _ in range(H)]; globally_used=[[False]*W for _ in range(H)]
 for color in set(x for row in grid for x in row if x!=bg):
  used=[[False]*W for _ in range(H)]
  while True:
   pref=[[0]*(W+1) for _ in range(H+1)]
   for r in range(H):
    for c in range(W):
     pref[r+1][c+1]=pref[r][c+1]+pref[r+1][c]-pref[r][c]+(grid[r][c]==color and not used[r][c])
   best=None
   for r1 in range(H):
    for r2 in range(r1+2,H+1):
     h=r2-r1
     for c1 in range(W-1):
      for c2 in range(c1+2,W+1):
       w=c2-c1; area=h*w
       n=pref[r2][c2]-pref[r1][c2]-pref[r2][c1]+pref[r1][c1]
       if n/area < min_density: continue
       if any(not any(grid[r][c]==color and not used[r][c] for c in range(c1,c2)) for r in range(r1,r2)): continue
       if any(not any(grid[r][c]==color and not used[r][c] for r in range(r1,r2)) for c in range(c1,c2)): continue
       bg_count=sum(grid[r][c]==bg for r in range(r1,r2) for c in range(c1,c2))
       other_count=area-n-bg_count
       score=n-noise_penalty*other_count-bg_penalty*bg_count
       if score<=0: continue
       key=(score,n,area)
       if best is None or key>best[0]: best=(key,r1,r2,c1,c2)
   if best is None: break
   _,r1,r2,c1,c2=best
   # don't allow object rectangles of same color to overlap; candidates masked by chosen box
   for r in range(r1,r2):
    for c in range(c1,c2):
     out[r][c]=color; used[r][c]=True
 return out

